// === Tab: Metaballs ===
// ########################################################## //
// #                                                        # //
// #        A 2D Metaball implementation using WEBGL        # //
// #       The ball movement is calculated on the CPU       # // 
// #      and rendering is done via a shader on the GPU      # //
// #                                                        # //
// ########################################################## //
// #                                                        # //
// #                Written by Fabian Kober                 # //
// #                  fabian-kober@gmx.net                  # //
// #                                                        # //
// ########################################################## //
let time;

// simulation speed, can be changed via the real time menu
let speed = 5;

// scale factor of the distance field, can be changed via the real time menu
let distScale = 0.25;

// color offset for the distance field visualization, can be changed via the real time menu
let colorOffset = 0.05;

// max radius of the balls, can be changed via the real time menu
let maxRadius = 50;

// all ball positions
let ballsX = [];
let ballsY = [];

// all ball radii
let radii = [];

// all ball velocities
let vels = [];

// menu to change a bunch of values
let menu;

// the shader to render the metaballs
let sh;

function setup() {
    // create the WEBGL canvas and the shader
    createCanvas(1112, 834, WEBGL);
    sh = createShader(vert, frag);

    // create menu and hide it
    menu = new Menu(42, 10);
    menu.toggle();

    // add some balls
    for (let i = 0; i < 150; ++i) {
        addBall(random(width/4, width/4*3), random(height/4, height/4*3), random(maxRadius));
    }

	now = performance.now();
}

function draw() {
    // simulate
    updateBalls();

    // set the shader and all uniforms
    shader(sh);
    sh.setUniform('u_ballsX', ballsX);
    sh.setUniform('u_ballsY', ballsY);
    sh.setUniform('u_radii', radii);
    sh.setUniform('u_balls', ballsX.length);
    sh.setUniform('u_distScale', distScale);
    sh.setUniform('u_colorOffset', colorOffset);
    sh.setUniform('u_width', width);
    sh.setUniform('u_height', height);

    // render a quad with the shader
    quad(-1, -1, -1, 1, 1, 1, 1, -1);

	if (frameCount%100 == 0) {
		console.log("frameRate(): " + frameRate() + ", average: " + 100 * 1000 / (performance.now() - time)); 
		time = performance.now();
	}
}

// handle mouse drag
function mouseDragged() {
    addBall((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), random(maxRadius));
}

// handle key presses
function keyPressed() {
    switch (key) {
        case ' ':
            menu.toggle();
            break;
			  case 's':    
				    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
				    break;
        case 'x':
        case 'X':
            clearField();
    break;
    }
}

// simulate the ball movement
function updateBalls() {
    for (let i = 0; i < vels.length; ++i) {
        // move the ball
        ballsX[i] += vels[i].x*speed;
        ballsY[i] += vels[i].y*speed;

        // collide with window edges
        if (ballsX[i]+radii[i] >= width || ballsX[i]-radii[i] <= 0)
            vels[i].x *= -1;
        if (ballsY[i]+radii[i] >= height || ballsY[i]-radii[i] <= 0)
            vels[i].y *= -1;
    }
}

// adds a ball at the provided location with the provided radius
function addBall(x, y, r) {
    ballsX.push(x);
    ballsY.push(y);
    radii.push(r);

    vels.push(createVector(random(-1,1), random(-1,1)));
}

// deletes all balls
function clearField() {
    ballsX = [];
    ballsY = [];
    radii = [];
    vels = [];
}

// === Tab: MetaballsShader ===
let vert = `
attribute vec4 aPosition;

varying vec2 v_uv;

void main() {
    // calculate uvs
    v_uv = aPosition.xy;
    v_uv.y *= -1.0;
    v_uv.x = v_uv.x * 0.5 + 0.5;
    v_uv.y = v_uv.y * 0.5 + 0.5; 

    // set position
    gl_Position = aPosition;
}
`;

let frag = `
precision mediump float;

#define MAX_BALLS 300

// ball positions
uniform float u_ballsX[MAX_BALLS];
uniform float u_ballsY[MAX_BALLS];

// ball radii
uniform float u_radii[MAX_BALLS];

// number of balls we actually have (because arrays have to be defined with a constant size)
uniform int u_balls;

// distance field variables
uniform float u_distScale;
uniform float u_colorOffset;

// width and height of the canvas
uniform float u_width;
uniform float u_height;

varying vec2 v_uv;

void main() {
    // this variable will hold our distance field info
    float df = 0.0; 

    // go through all balls (we have to bail out manually because for loops have to be declared with a constant value in WEBGL)
    for(int i = 0; i < MAX_BALLS; ++i) {
        if(i >= u_balls)
            break;

        // calculate the vector between this pixel and the current ball
        vec2 diff = vec2(u_ballsX[i], u_ballsY[i]) - vec2(v_uv.x*u_width, v_uv.y*u_height);

        // add the scaled distance to the distance field
        df += u_radii[i] * u_distScale/length(diff);
    }

    // calculate a color from the distance field
    gl_FragColor = vec4(mod(df+u_colorOffset,1.0),mod(df+u_colorOffset*2.0,1.0),mod(df+u_colorOffset*3.0,1.0), 1.0);
}
`;

// === Tab: Menu ===
// container for the menu
class Menu {
    // creates the menu at the provided position
    constructor(x, y) {
        this.x = x;
        this.y = y;

        // spacing between the elements
        this.spacing = 5;

        // flag whether the menu is hidded atm
        this.hidden = false;

        // start y pos
        let elemY = y;

        // a parent div containing all menu elements
        this.parentDiv = createDiv('');
        this.parentDiv.style('color', '#ffffffff');

        // Label for Speed input field
        this.speedInputLabel = createDiv("Speed:");
        this.speedInputLabel.position(x, elemY);
        this.speedInputLabel.parent(this.parentDiv);
        elemY += this.distToNextY(this.speedInputLabel);

        // speed input field
        this.speedInput = createInput(speed, 'number');
        this.speedInput.position(x, elemY);
        this.speedInput.parent(this.parentDiv);
        this.speedInput.changed(value => speed = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.speedInput);

        // Label for distance scale value input field
        this.distScaleInputLabel = createDiv("Distance Scale:");
        this.distScaleInputLabel.position(x, elemY);
        this.distScaleInputLabel.parent(this.parentDiv);
        elemY += this.distToNextY(this.distScaleInputLabel);

        // distance scale Input field
        this.distScaleInput = createInput(distScale, 'number');
        this.distScaleInput.position(x, elemY);
        this.distScaleInput.parent(this.parentDiv);
        this.distScaleInput.changed(value => distScale = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.distScaleInput);

        // Label for color offset value input field
        this.colorOffsetInputLabel = createDiv("Color Offset:");
        this.colorOffsetInputLabel.position(x, elemY);
        this.colorOffsetInputLabel.parent(this.parentDiv);
        elemY += this.distToNextY(this.colorOffsetInputLabel);

        // color offset Input field
        this.colorOffsetInput = createInput(colorOffset, 'number');
        this.colorOffsetInput.position(x, elemY);
        this.colorOffsetInput.parent(this.parentDiv);
        this.colorOffsetInput.changed(value => colorOffset = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.colorOffsetInput);

        // Label for max radius value input field
        this.maxRInputLabel = createDiv("Max Radius:");
        this.maxRInputLabel.position(x, elemY);
        this.maxRInputLabel.parent(this.parentDiv);
        elemY += this.distToNextY(this.maxRInputLabel);

        // max radius Input field
        this.maxRInput = createInput(maxRadius, 'number');
        this.maxRInput.position(x, elemY);
        this.maxRInput.parent(this.parentDiv);
        this.maxRInput.changed(value => maxRadius = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.maxRInput);

        // Button to clear the field
        this.clearFieldButton = createButton("Clear");
        this.clearFieldButton.position(x, elemY);
        this.clearFieldButton.parent(this.parentDiv);
        this.clearFieldButton.mouseClicked(clearField);
    }

    // gets the difference to the next y position
    distToNextY(element) {
        return element.size().height + this.spacing;
    }

    toggle() {
        if (this.hidden) {
            this.parentDiv.show();
        } else {
            this.parentDiv.hide();
        }

        this.hidden = !this.hidden;
    }
}

